// =========================================================================
// constructor / destructor
// =========================================================================

SMOKEMAXCtx::SMOKEMAXCtx(ot::Mesh *pMesh)
    : ts::Ctx<SMOKEMAXCtx, DendroScalar, unsigned int>() {

    m_uiMesh = pMesh;

    // evolution variables
    m_var[VL::CPU_EV].create_vector(m_uiMesh, ot::DVEC_TYPE::OCT_SHARED_NODES,
        ot::DVEC_LOC::HOST, 24, true);
    m_var[VL::CPU_EV_UZ_IN].create_vector(m_uiMesh,
        ot::DVEC_TYPE::OCT_LOCAL_WITH_PADDING, ot::DVEC_LOC::HOST,
        24, true);
    m_var[VL::CPU_EV_UZ_OUT].create_vector(m_uiMesh,
        ot::DVEC_TYPE::OCT_LOCAL_WITH_PADDING, ot::DVEC_LOC::HOST,
        24, true);

    // constraint variables
    m_var[VL::CPU_CV].create_vector(m_uiMesh, ot::DVEC_TYPE::OCT_SHARED_NODES,
        ot::DVEC_LOC::HOST, 6, true);
    m_var[VL::CPU_CV_UZ_IN].create_vector(m_uiMesh,
        ot::DVEC_TYPE::OCT_LOCAL_WITH_PADDING, ot::DVEC_LOC::HOST,
        6, true);

    // analytical solution and difference vectors
    m_var[VL::CPU_ANALYTIC].create_vector(m_uiMesh, ot::DVEC_TYPE::OCT_SHARED_NODES,
        ot::DVEC_LOC::HOST, 24, true);
    m_var[VL::CPU_ANALYTIC_DIFF].create_vector(m_uiMesh, ot::DVEC_TYPE::OCT_SHARED_NODES,
        ot::DVEC_LOC::HOST, 24, true);

    m_uiBHLoc[0] = Point(SMOKEMAX_BH_LOC[0].x(),
                         SMOKEMAX_BH_LOC[0].y(),
                         SMOKEMAX_BH_LOC[0].z());
    m_uiBHLoc[1] = Point(SMOKEMAX_BH_LOC[1].x(),
                         SMOKEMAX_BH_LOC[1].y(),
                         SMOKEMAX_BH_LOC[1].z());
    m_bIsBHMerged = false;
    m_dMergeTime = std::numeric_limits<double>::max();
    m_uiMergeStep = std::numeric_limits<uint32_t>::max();
    m_bConstraintsComputed = false;
    m_uiWroteGridInfoHeader = false;

    // time stepping info
    m_uiTinfo._m_uiStep = 0;
    m_uiTinfo._m_uiT = 0;
    m_uiTinfo._m_uiTh = SMOKEMAX_RK45_TIME_STEP_SIZE;

    // allocate MPI communication context for async ghost exchange
    ot::alloc_mpi_ctx<DendroScalar>(m_uiMesh, m_mpi_ctx, 24,
                                     SMOKEMAX_ASYNC_COMM_K);
}

SMOKEMAXCtx::~SMOKEMAXCtx() {
    ot::dealloc_mpi_ctx<DendroScalar>(m_uiMesh, m_mpi_ctx, 24,
                                       SMOKEMAX_ASYNC_COMM_K);
    for (unsigned int i = 0; i < VL::END; i++) {
        m_var[i].destroy_vector();
    }
}

// =========================================================================
// initialization
// =========================================================================

int SMOKEMAXCtx::initialize() {
    if (SMOKEMAX_RESTORE_SOLVER) {
        // initialize() is called again from ets->init(); restore exactly once
        // so we don't re-read the checkpoint / rebuild the mesh a second time.
        if (!m_bCheckpointRestored) {
            restore_checkpt();
            m_bCheckpointRestored = true;
        }
        return 0;
    }

    init_grid();
    return 0;
}

int SMOKEMAXCtx::init_grid() {
    if (!m_uiMesh->isActive()) return 0;

    DVec &m_evar = m_var[VL::CPU_EV];

    const ot::TreeNode *pNodes = &(*(m_uiMesh->getAllElements().begin()));
    const unsigned int eleOrder = m_uiMesh->getElementOrder();
    const unsigned int *e2n_cg = &(*(m_uiMesh->getE2NMapping().begin()));
    const unsigned int *e2n_dg = &(*(m_uiMesh->getE2NMapping_DG().begin()));
    const unsigned int nPe = m_uiMesh->getNumNodesPerElement();
    const unsigned int nodeLocalBegin = m_uiMesh->getNodeLocalBegin();
    const unsigned int nodeLocalEnd = m_uiMesh->getNodeLocalEnd();

    DendroScalar *zipIn[24];
    m_evar.to_2d(zipIn);

    // two-punctures: do the elliptic solve first (collective, all ranks)
    double mp, mm, mp_adm, mm_adm, E, J1, J2, J3;
    double var1[24];
    if (SMOKEMAX_ID_TYPE == 0) {
        TP_MPI_COMM = m_uiMesh->getMPIGlobalCommunicator();
        TwoPunctures(0.0, 0.0, 0.0, var1, &mp, &mm, &mp_adm, &mm_adm,
                     &E, &J1, &J2, &J3);
    }

    for (unsigned int elem = m_uiMesh->getElementLocalBegin();
         elem < m_uiMesh->getElementLocalEnd(); elem++) {

        DendroScalar var[24];

        for (unsigned int k = 0; k < (eleOrder + 1); k++)
            for (unsigned int j = 0; j < (eleOrder + 1); j++)
                for (unsigned int i = 0; i < (eleOrder + 1); i++) {

                    const unsigned int nodeLookUp_CG =
                        e2n_cg[elem * nPe +
                               k * (eleOrder + 1) * (eleOrder + 1) +
                               j * (eleOrder + 1) + i];

                    if (nodeLookUp_CG >= nodeLocalBegin &&
                        nodeLookUp_CG < nodeLocalEnd) {

                        const unsigned int nodeLookUp_DG =
                            e2n_dg[elem * nPe +
                                   k * (eleOrder + 1) * (eleOrder + 1) +
                                   j * (eleOrder + 1) + i];

                        unsigned int ownerID, ii_x, jj_y, kk_z;
                        m_uiMesh->dg2eijk(nodeLookUp_DG, ownerID, ii_x, jj_y, kk_z);

                        const DendroScalar len =
                            (double)(1u << (m_uiMaxDepth - pNodes[ownerID].getLevel()));
                        const DendroScalar x =
                            pNodes[ownerID].getX() + ii_x * (len / eleOrder);
                        const DendroScalar y =
                            pNodes[ownerID].getY() + jj_y * (len / eleOrder);
                        const DendroScalar z =
                            pNodes[ownerID].getZ() + kk_z * (len / eleOrder);

                        if (SMOKEMAX_ID_TYPE == 0) {
                            // tp solver: interpolate the stored solution
                            TwoPunctures(
                                (double)GRIDX_TO_X(x), (double)GRIDY_TO_Y(y),
                                (double)GRIDZ_TO_Z(z), var,
                                &mp, &mm, &mp_adm, &mm_adm, &E, &J1, &J2, &J3);
                        } else {
                            initDataFuncToPhysCoords((double)x, (double)y, (double)z, var);
                        }

                        for (unsigned int v = 0; v < 24; v++)
                            zipIn[v][nodeLookUp_CG] = var[v];
                    }
                }
    }

    // enforce evolution constraints on initial data
    for (unsigned int node = nodeLocalBegin; node < nodeLocalEnd; node++) {
        enforce_smokemax_constraints(zipIn, node);
    }

    return 0;
}

// =========================================================================
// rhs -- unzip, call generated equations, zip back
// =========================================================================

int SMOKEMAXCtx::rhs(DVec *in, DVec *out, unsigned int sz,
                                DendroScalar time) {

    smokemax::timer::t_unzip_async.start();
    this->unzip(*in, m_var[VL::CPU_EV_UZ_IN], SMOKEMAX_ASYNC_COMM_K);
    smokemax::timer::t_unzip_async.stop();

    DendroScalar *unzipIn[24];
    DendroScalar *unzipOut[24];

    m_var[CPU_EV_UZ_IN].to_2d(unzipIn);
    m_var[CPU_EV_UZ_OUT].to_2d(unzipOut);

    const ot::Block *blkList = m_uiMesh->getLocalBlockList().data();
    const unsigned int numBlocks = m_uiMesh->getLocalBlockList().size();

    DendroScalar *unzipConsIn[6];
    m_var[CPU_CV_UZ_IN].to_2d(unzipConsIn);

    smokemaxRHS(
        unzipOut, (const double **)unzipIn,
        blkList, numBlocks, time,
        (const double **)unzipConsIn
    );

    smokemax::timer::t_zip.start();
    this->zip(m_var[CPU_EV_UZ_OUT], *out);
    smokemax::timer::t_zip.stop();

    return 0;
}

// =========================================================================
// stage / timestep hooks
// =========================================================================

int SMOKEMAXCtx::pre_stage(DVec &sIn) { return 0; }
// post_stage receives the RK stage derivative, not a state -- enforcement of
// algebraic constraints happens in post_timestep, which the ETS already calls
// on every intermediate stage state.
int SMOKEMAXCtx::post_stage(DVec &sIn) { return 0; }
int SMOKEMAXCtx::pre_timestep(DVec &sIn) { return 0; }

int SMOKEMAXCtx::post_timestep(DVec &sIn) {
    if (!m_uiMesh->isActive()) return 0;

    DendroScalar *zipIn[24];
    sIn.to_2d(zipIn);

    const unsigned int nodeLocalBegin = m_uiMesh->getNodeLocalBegin();
    const unsigned int nodeLocalEnd = m_uiMesh->getNodeLocalEnd();

    for (unsigned int node = nodeLocalBegin; node < nodeLocalEnd; node++) {
        enforce_smokemax_constraints(zipIn, node);
    }

    return 0;
}

