// =========================================================================
// constraint computation
// =========================================================================

void SMOKEMAXCtx::compute_constraint_variables() {
    if (m_bConstraintsComputed) return;
    if (!m_uiMesh->isActive()) return;

    DVec &m_evar = m_var[VL::CPU_EV];

    this->unzip(m_evar, m_var[VL::CPU_EV_UZ_IN], SMOKEMAX_ASYNC_COMM_K);

    DendroScalar *unzipIn[24];
    DendroScalar *unzipConsOut[6];

    m_var[CPU_EV_UZ_IN].to_2d(unzipIn);
    m_var[CPU_CV_UZ_IN].to_2d(unzipConsOut);

    const ot::Block *blkList = m_uiMesh->getLocalBlockList().data();
    const unsigned int numBlocks = m_uiMesh->getLocalBlockList().size();

    smokemaxConstraints(unzipConsOut, (const double **)unzipIn,
                                  blkList, numBlocks);

    this->zip(m_var[CPU_CV_UZ_IN], m_var[VL::CPU_CV]);

    m_uiMesh->readFromGhostBegin(m_var[VL::CPU_CV].get_vec_ptr(),
                                  m_var[VL::CPU_CV].get_dof());
    m_uiMesh->readFromGhostEnd(m_var[VL::CPU_CV].get_vec_ptr(),
                                m_var[VL::CPU_CV].get_dof());

    m_bConstraintsComputed = true;
}

